vector<int> readIntegerFile(std::string_view filename) {
    std::ifstream inputStream{filename.data()};
    if (inputStream.fail()) {
        throw FileOpenError{std::string(filename)};
    }

    vector<int> integers;
    std::size_t lineNumber{0};
    while (!inputStream.eof()) {
        std::string line;
        std::getline(inputStream, line);
        ++lineNumber;

        std::istringstream lineStream{line};
        int temp;
        while (lineStream >> temp) {
            integers.push_back(temp);
            if (!lineStream.eof()) {
                throw FileReadError{std::string(filename), lineNumber};
            }
        }
    }
    return integers;
}

错误分类关系：
$$
\text{文件错误} = \begin{cases}
\text{FileOpenError}, & \text{文件无法打开}\\
\text{FileReadError}, & \text{文件已打开但某行无法正确读取}
\end{cases}
$$
